"""Reviewed 4.0.3 editorial update. Builds artifacts only; never publishes."""
from pathlib import Path
import json,re,copy
ROOT=Path(__file__).resolve().parents[2]
BASE=json.loads((ROOT/'Reports/help-update-2026-10-16/before.json').read_text())
articles=copy.deepcopy(BASE['articles']); A={a['slug']:a for a in articles}
DATE='2026-10-16T12:00:00+00:00'
shots={}
def update(slug,steps=None,body=None,note=None,title=None,route=None,summary=None,images=None):
 a=A[slug]
 for k,v in [('steps',steps),('body',body),('note',note),('title',title),('route',route),('summary',summary)]:
  if v is not None:a[k]=v.split('|') if k in ('steps','body') and isinstance(v,str) else v
 if images:shots[slug]=images.split()
def add(slug,cat,title,summary,route,steps,body,note,images,related):
 a=dict(slug=slug,category_id=cat,title=title,summary=summary,route=route,steps=steps.split('|'),body=body.split('|'),note=note,screenshot=None,tags=[],related=related.split(),status='published',published_at=DATE,updated_at=DATE,app_version='Oath 4.0.3',sort_order=200+len(articles))
 A[slug]=a;articles.append(a);shots[slug]=images.split()
# Replace obsolete availability, navigation and security instructions.
update('send-availability',title='Send coins and tokens',summary='Choose the right wallet, network, recipient and amount, then review and authorize a transfer.',route='Home → Send → asset → recipient → amount → review',steps='Check the active wallet on Home. Tap Send and choose the exact coin or token; the same ticker can exist on different networks.|Paste or scan the recipient address, or choose a saved contact. Compare the complete address and network with the recipient’s instructions.|Enter a destination tag or memo when the recipient requires one. Continue only after any address or memo validation is resolved.|Enter the amount in asset units, or switch to local currency when a usable price is available. Max leaves room for the applicable fees and reserves.|Continue to review. Check the wallet, network, asset, recipient, amount and maximum network fee. Read any activation, reserve or token-registration guidance.|Confirm and authenticate when requested. Keep the result open until Oath reports a submission or an error; a review screen alone does not send funds.|Open the resulting transaction in History. Use its status and explorer record to distinguish pending from confirmed. If a response is uncertain, check the existing transaction before trying another transfer.',body='Sending is available for supported assets on Bitcoin-family networks, EVM networks, TRON, Solana, Gram, Aptos, Sui, NEAR, XRP Ledger, Stellar and THORChain. The selected asset’s flow determines what is supported; a discoverable token is not a guarantee that every unusual token standard can be sent.|The displayed local-currency amount is an estimate. The quantity in asset units is what the transfer spends. Fee estimates and spendable balances may change during review, so Oath can require you to review again.|Insufficient gas, an invalid recipient, a locked wallet or a failed network check can prevent submission. Correct the specific issue and review again. Never treat an error as proof that an earlier uncertain submission cannot have reached the network.',note='A direct send stays on the selected network. It does not swap assets or bridge funds to another chain.',images='06-send-assets send-recipient send-amount wc-send')
update('permissions',title='Review wallet permissions and connected apps',summary='Inspect token allowances, NFT access, connected apps and supported account-control permissions for the selected wallet.',route='Settings → Permissions',steps='Open Settings → Permissions and check the wallet shown at the top. Select a different wallet there if needed.|Wait for the scan to finish, then open Token access, NFT access or Account control to see the permissions found for that wallet.|Read the network group and exact asset or contract on each row. Open a row to inspect the approved address and scope of its access.|Open Connected apps to manage WalletConnect sessions. Disconnecting a session and revoking on-chain access are separate actions.|Use the filter menu’s Select action for multiple removals, or swipe a removable row. Review the revocation and fees before confirming.|After submission, check removal history and refresh the scan. Read Coverage for partial, unavailable or unindexed networks.',body='EVM standard allowances and NFT approvals, TRON TRC-20 approvals and Solana SPL/Token-2022 delegates have different removal instructions. Oath prepares the supported action for each permission rather than treating every chain alike.|An asset name or logo helps you recognize a row, but it is not evidence that the contract is safe. Compare the full network and addresses. Some contracts have no reliable name and remain identified by their address.|Unknown off-chain signatures, custom contracts and some account-level privileges cannot be comprehensively discovered. A blank list is not a certificate that the wallet has no permissions.',note='Revocations are network transactions and require fees. Removing a token from view, deleting a local wallet or disconnecting a dApp does not revoke its on-chain allowance.',images='help-permissions permission-list permission-review')
update('home-screen',steps='Open the Wallet tab to see the active wallet’s total and Assets list.|Use the wallet-name capsule in the top toolbar to switch wallets. The adjacent sliders action opens Settings; the scanner opens the shared QR scanner.|Read the balance-change capsule under the total as an observed change in this wallet’s value. It is not a profit report or a button for a balance-history chart.|Tap Send or Receive for a transfer flow. Tap an asset for its price, actions and activity.|Select Wallet and then the separate Search icon to search assets, including an exact contract or mint address.|Open History for transactions across the active wallet. Pull down from the top to refresh; cached information can remain visible while newer data arrives.',images='01-portfolio 07-wallets')
update('switch-wallet',steps='Return to Home and tap the wallet-name capsule in the top toolbar.|Find the intended wallet by name and color. The check badge marks the active wallet.|Tap its row and wait for Home to load that wallet. Read the name in the toolbar before continuing.|Open Receive and compare the public address for the intended network, especially when two wallets have similar names.|To add another wallet, use the create, import, private-key import or iCloud restore actions in the switcher or Settings → Wallets.',images='07-wallets 01-portfolio')
update('app-switcher-privacy',steps='Open Settings → Passcode & Face ID and authenticate if requested.|Enable App Switcher Privacy.|Move Oath to the background. Its app-switcher preview is blurred; the privacy cover no longer adds a central Oath logo.|Return to Oath. Complete unlock if your passcode timing requires it.',body='The blur hides the app’s preview when switching between apps. It does not change your blockchain address, encrypt a screenshot you share, or conceal public transactions.|Hide Balances is a separate display setting. Use it when you want amounts obscured while you are actively showing the app.',images='09-security')
update('recover-deleted-wallet',steps='Open Settings → Wallets → Recently Deleted before the displayed deletion deadline.|Select the wallets to restore. Use Select All or Unselect All to change the selection.|Tap Restore. Complete authentication if requested and wait for the operation to finish.|Return to Wallets, choose the restored wallet and check its receiving address and refreshed assets.',body='Removed wallets normally remain recoverable locally for seven days. Each row shows its own deadline; expired items are permanently removed the next time Oath is unlocked.|Restore returns the retained wallet to the active list. If it was permanently deleted, use its original recovery material or encrypted iCloud backup instead.|Removing the final active wallet is a different flow: it requires clearing Recently Deleted and then resets the local app.',images='help-recently-deleted 07-wallets')
update('permanently-delete-wallet',steps='Open Recently Deleted and select the wallets you intend to erase. Compare their names and deletion dates.|Check that you have an independently usable recovery phrase, private key or encrypted backup for anything you may need later.|Tap Delete Permanently, the destructive secondary button below Restore.|Read the confirmation and authenticate if requested. Confirm only the selected wallets you intend to erase.|After completion, verify those rows are gone. A permanently deleted wallet cannot be restored from Recently Deleted.',images='help-recently-deleted')
update('remove-wallet',body='For an ordinary removal while other active wallets remain, the wallet enters Recently Deleted for seven days. This affects the local app, not funds or token approvals on the blockchain.|Removing the final active wallet instead follows a reset flow. If Recently Deleted contains wallets, Oath asks you to permanently remove those first. Cancel if you do not have recovery material for them.|After the final active wallet is removed, Oath returns to Welcome. Existing iCloud files are separate from the local deletion; protect their passwords and remove cloud copies separately only if that is your intention.',images='07-wallets help-recently-deleted')
update('transaction-details',steps='Open History or an asset’s Activity and tap a transaction.|Read the asset logo and action/status badge, then compare the asset quantity with the local-currency estimate.|Check Status, Time, Network and the available Network fee. Pending, failed, canceled and replaced entries do not all mean a successful transfer.|Use the copy buttons for full addresses and the transaction ID. Shortened text on the screen is only a display abbreviation.|Tap the ellipsis in the top toolbar for Share Screenshot, Share Link or View on Explorer.',body='The header uses the coin or token logo with an action or status badge. Read the text status as well; an icon alone is not sufficient to establish confirmation.|The fee is a network cost, separate from the transferred quantity. A failed on-chain transaction can still consume fees. Missing information remains unavailable rather than being invented.|Explorer and share-link actions use the transaction’s network. A receipt image is convenient to share, but a recipient should verify the public transaction and its outcome.',images='04-transaction')
update('share-transaction',route='Transaction details → ellipsis',steps='Open the transaction whose receipt or public link you want to share.|Tap the ellipsis (…) in the top toolbar.|Choose Share Screenshot for the receipt image, or Share Link for the network-specific explorer URL when available.|Review the iOS share sheet, including the preview and destination, before sending.|Use View on Explorer from the same menu when you want to inspect the record yourself.',images='04-transaction')
update('view-explorer',route='Transaction details → ellipsis → View on Explorer',steps='Open a transaction in History or an asset’s Activity.|Tap the ellipsis in the top toolbar and choose View on Explorer.|Verify that the explorer network and full transaction ID match the transaction you opened.|Read confirmation status and the actual transfers or events. A transaction may contain several actions.|Close the browser to return to Oath. Share Link in the same menu shares the public record without opening it first.',images='04-transaction')
update('receive-crypto',steps='Choose the correct active wallet, then tap Receive on Home and select an asset. Receive on an asset screen opens that asset directly.|Check the sheet title, such as Receive Ethereum, and the network guidance directly beneath the QR code.|If an address-type or derivation selector appears in the top toolbar, choose the intended account format before sharing.|Read the full address near the bottom above Copy address and Share. Compare it with the wallet and network you intend to fund.|Let the sender scan the QR, or copy/share the public address. The QR encodes the address; the sender must also choose the correct network and asset.|After the sender broadcasts, refresh Home and check History. Use the transaction’s explorer record if confirmation or indexing is still pending.',body='The QR is generated by the native iOS QR pipeline. The central asset mark is visual identification; always read the network and address as well.|The assets row or About this address explains what the selected network can receive. Examples do not mean every token on every other chain can be deposited here.|Receive does not require signing a transaction. It does not set a requested amount or add a card to Apple Wallet. You can share the public address without sharing recovery words or a private key.',images='05-receive receive-about')
update('copy-share-address',steps='Open Receive for the intended wallet and asset.|If necessary, choose the address type or Solana path from the top toolbar first.|Tap Copy address to copy the full address, or Share to open the native share sheet.|Tell the sender the exact network alongside the address. Sharing an address does not bridge between networks.|Ask the sender to compare the full address and complete a small test payment when appropriate before a larger transfer.',images='05-receive')
update('receive-network-tokens',route='Receive → assets row or About this address',steps='Open Receive for the intended network and read the sentence below the QR.|Tap the supported-assets row or About this address.|Read the network-specific explanation and compare the token’s actual contract or mint with the one you intend to receive.|Return to the QR and copy/share the address for that same network.|After a transfer, use asset search to add a supported token by its exact identity if discovery has not listed it.',images='05-receive receive-about')
update('bitcoin-address-types',route='Bitcoin → Receive → top-toolbar address options',images='receive-bitcoin receive-bitcoin-types')
update('solana-address-path',route='Solana → Receive → top-toolbar address options',images='receive-solana receive-solana-types')
update('refresh-balances',body='Pull-to-refresh belongs to the native scroll view. The Oath logo animates in the refresh area while the current content remains available.|Refresh requests updated balances and available activity; it does not send funds or guarantee a provider has indexed a just-broadcast transaction. An unchanged result can be correct.|If refresh fails, retain the transaction ID and compare the same network in its explorer. Check the active wallet, any asset/history filters and connectivity before repeating.',images='01-portfolio 03-activity')
update('app-icon',steps='Open Settings → Appearance → App Icon.|Choose from Signal Blue, Obsidian, Porcelain, Verdant, Ultraviolet, Electric Lime, Ember, Titanium, Glacier and Champagne.|Tap the design you want. Wait for iOS to accept the icon change.|The checkmark identifies the active choice. Return to the Home Screen to see the launcher icon.',body='Signal Blue is the primary app icon. The previous Original, Light, Dark and Monochrome choices have been replaced by the new collection.|Changing the launcher icon does not rename a wallet, change its addresses or alter its artwork color. Use Customize Wallet for wallet-specific appearance.|If an icon change is unavailable or fails, leave Oath active and try again. The checkmark should reflect the choice accepted by iOS.',images='10-app-icons help-appearance')
# Chain articles: replace obsolete sending caveats and add network-specific transfer detail.
chain_details={
'use-solana':('Solana','SOL','Keep SOL for fees and any token-account creation. Check the selected Phantom/Trust Wallet derivation before receiving. WalletConnect also supports explicitly approved Devnet and Testnet requests; these are separate from mainnet balances.'),
'use-tron':('TRON','TRX','TRC-20 transfers may consume Energy and Bandwidth, with TRX burned when resources are insufficient. Recipient activation and token-transfer costs can differ from a simple TRX transfer; review the estimate.'),
'use-gram':('Gram','GRAM','Use the address format shown for the Gram/TON account and the correct jetton identity. Enter an exchange memo/comment exactly when required. Fees and a retained reserve can make Max smaller than the headline balance.'),
'use-aptos':('Aptos','APT','Keep APT for gas. A token can use a coin type or fungible-asset reference; compare its full identity. Review recipient registration or asset-store guidance before authorizing.'),
'use-sui':('Sui Network','SUI','Keep SUI for gas. Coin type identifies the token. A 0x address alone does not establish the network; verify Sui with the recipient.'),
'use-near':('NEAR Protocol','NEAR','Compare the complete named or implicit account with the intended recipient. Fungible-token transfers may need recipient storage registration; review any deposit and remaining NEAR requirements.'),
'use-xrp-ledger':('XRP Ledger','XRP','Enter the exchange’s destination tag when required. Issued assets are identified by currency and issuer. Account reserves and trust lines affect spendable funds; account closure is a separately reviewed action when offered.'),
'use-stellar':('Stellar','XLM','Choose the correct memo type and exact value required by an exchange. Issued assets are identified by code and issuer; trust lines, minimum balances and recipient activation can affect a transfer.'),
'use-bitcoin-cash':('Bitcoin Cash','BCH','Use the Bitcoin Cash address and supported format. A Bitcoin transaction and a Bitcoin Cash transaction are separate; a familiar-looking address is not enough to select a network.'),
'use-dogecoin':('Dogecoin','DOGE','Use the DOGE receive address. Available UTXOs and the estimated fee determine the amount you can send. Wait for a transaction outcome before sending a replacement.'),
'use-litecoin':('Litecoin','LTC','Check the supported address type in Receive and the sending service’s format support. UTXO selection and fees affect Max; address types do not move funds between networks.')}
for slug,(name,symbol,detail) in chain_details.items():
 a=A[slug]; update(slug,summary=f'Receive, send and inspect {name} assets using the correct account and network.',steps=f'Open Wallet → Search and find {name} or {symbol}. Select the intended native asset or token.|Read the quantity, available price and Activity. Use Asset Information to verify a token’s full identity.|Tap Receive, check the network notice and copy the complete public address. {"Check the top-toolbar path selector if recovering a different Solana account." if slug=="use-solana" else "Confirm the sending service supports this exact network."}|For an outgoing transfer, tap Send, enter the recipient and any required memo or tag, then choose an amount.|Review the fee and any account requirements before confirming. Complete authentication when requested.|Check the transaction’s status and use the ellipsis → View on Explorer to verify its public outcome.',body=detail+'|Discovery, activity and price coverage can differ between native assets and tokens. If a quote is unavailable, the token quantity can still be correct; do not interpret missing market data as a zero price.|Check the active wallet before every action. Imported private keys may expose fewer accounts or address types than a full recovery-phrase wallet.',images='chain-'+{'use-gram':'ton','use-xrp-ledger':'xrpl','use-sui':'sui','use-near':'near'}.get(slug,slug[4:])+' 06-send-assets')
update('evm-networks',body='The current EVM catalog includes Ethereum, Arbitrum, Arc, Avalanche C-Chain, Base, BNB Smart Chain, Fantom, Flare, Gnosis, HyperEVM, Linea, Monad, Optimism, Polygon, Robinhood Chain, Scroll, Somnia, Story, Taiko, Telos EVM, Unichain and X Layer.|A contract address is meaningful together with its network. Even when two chains use the same 0x account address, their coins, tokens, approvals and transaction histories remain separate.|Direct sends stay on the selected network. A dApp swap or bridge can involve separate approvals and transactions; review each request and never infer a destination chain from the token ticker alone.',note='Keep the network’s fee asset available for token transfers. Arc is a special case with native USDC; follow its own fee review.',images='chain-ethereum 06-send-assets')
# Source-guided new guides.
add('send-max-and-fees','activity','Use Max and understand spendable balance','See why the maximum you can send may be lower than the total displayed on Home.','Send → amount → Max → review','Select the intended asset and enter the recipient first.|Tap Max on the amount page. Read the resulting quantity in asset units.|For token transfers, check that you also hold the network’s native fee asset.|Continue to review and read the network fee plus any activation, reserve or storage requirement.|If the available amount changes, return to amount and calculate Max again. Confirm only after reviewing the updated total.|Check History after submission; do not repeatedly send because a balance refresh is delayed.','Native-coin Max needs to leave enough for transaction costs. UTXO fees depend on inputs and transaction size; account-based networks may retain mandatory balances or reserves.|For a token, the entire token balance may be transferable while a different native asset pays gas. A token with no reliable quote can still be entered in asset units.|Fee estimates are network-specific and can change. A maximum fee is a spending limit or estimate used in that review, not a promise that the exact amount will be charged.','A displayed portfolio total is a valuation, not a promise that all of it is spendable.','send-amount wc-gas','send-availability network-fee')
add('send-tags-and-memos','activity','Enter destination tags and memos','Include the extra reference an exchange or shared receiving account needs to credit your transfer.','Send → recipient → memo or destination tag','Open the recipient’s deposit instructions and confirm the asset and network.|In Oath, select that asset and paste the deposit address.|For XRP Ledger enter the requested destination tag. For Stellar select the required memo type before entering its exact value.|For other networks with a memo field, follow the recipient’s instructions exactly; do not invent a memo if none is required.|Review the address, memo/tag, amount and network together on the final screen.|After sending, retain the transaction ID. If an exchange does not credit it, contact that exchange with the public transaction details.','An exchange may use one address for many customers and distinguish deposits with a tag or memo. A valid address alone can therefore be insufficient.|Text memos, numeric IDs and hashes are different formats. Use the field and type displayed for the selected chain; leading characters and case can matter.|Oath cannot assign a missing deposit to your exchange account after broadcast. Do not resend a second payment merely to fix a tag on the first.','Memos and on-chain messages can become public. Never put a recovery phrase, private key, password or personal secret in them.','send-recipient','send-availability wrong-network')
add('bitcoin-transfer-options','activity','Set Bitcoin transfer options','Understand Replace by fee and the optional public on-chain message before sending.','Bitcoin → Send → amount → transfer options','Choose Bitcoin, enter the recipient and continue to the amount page.|Open Transfer options from the amount page.|Enable Replace by fee only if you want the transaction to signal replacement eligibility. The option is off by default.|Optionally enter an on-chain message. Read the byte count and network-specific limit.|Confirm the options with the checkmark, then review the updated transaction and fee.|After broadcast, use the transaction’s status and explorer to follow it. Enabling RBF does not itself submit a replacement.','The message is stored publicly with the transfer using OP_RETURN and contributes to transaction size and fees. A byte count is not necessarily the same as a character count.|Bitcoin node policies differ. Larger messages can be rejected by stricter nodes even when they fit the app’s supported limit.|RBF signals replacement policy; some Bitcoin nodes allow replacement even when that signal is off. The switch is not a guarantee that an unconfirmed transaction cannot be replaced.','Never put secrets in an on-chain message. Confirmed blockchain content cannot be edited like a chat message.','send-options send-amount','send-availability canceled-replaced network-fee')
add('send-troubleshooting','activity','Resolve a transfer that cannot be sent','Work out whether the problem is validation, fees, authorization, provider access or an uncertain submission.','Send → review or result','Read the error and identify whether it occurred before authorization, during submission or while waiting for confirmation.|Check the selected wallet, recipient network, token identity and any required memo or tag.|Check the native fee balance and account activation, reserve or registration guidance. Reduce the amount if needed.|If authentication was canceled, return to the review and authenticate again. Never enter your recovery phrase into a dApp or support form.|If Oath has a transaction ID or reports a pending/uncertain submission, inspect that same transaction in History or its explorer before attempting another transfer.|If it is definitely failed or rejected, correct the reason and make a fresh review. Contact support with the network, public transaction ID and error text if needed.','A local validation error normally means a transfer has not been prepared. A lost response after broadcast is different: the network may already have the transaction.|Simulation and preflight failures can reflect insufficient funds, slippage, a changed allowance or contract conditions. Repeatedly confirming unchanged data does not fix those conditions.|Keep Oath available for status checks. Background work can pause when iOS suspends the app; reopening and unlocking lets pending work resume.','Do not send recovery words, private keys, passcodes or raw signing payloads to support.','wc-simulation wc-pending','send-availability transaction-status network-fee')
add('connect-dapp','settings','Connect a dApp with WalletConnect','Approve the intended website, wallet and networks before responding to a dApp request.','dApp → Connect wallet → WalletConnect → Oath','Open the dApp from a trusted address and choose WalletConnect in its wallet connection options.|On another screen, scan its WalletConnect QR using Oath’s Home scanner. On the same device, choose the Oath link offered by the dApp.|Unlock Oath if asked. Read the connection proposal’s website identity and any verification warning.|Choose the intended wallet and approve only the networks you need. Review the methods being requested.|Connect, then return to the dApp. A connection shares the approved public accounts; it does not approve every future signature or transfer.|Review each later request independently. Manage the connection in Settings → WalletConnect or Permissions → Connected apps.','WalletConnect support depends on the namespace and request method. Oath supports EVM, THORChain and Solana request flows within their implemented limits; it does not imply every network in the portfolio supports every dApp.|A familiar name or icon can be copied. Compare the website origin and reject unexpected, blocked or unverified requests when you cannot establish why they appeared.|Pairing requests expire. If the proposal is no longer usable, start a fresh connection from the dApp instead of reusing an old QR.','Never share a WalletConnect pairing QR or URI publicly. Connecting does not require giving a site your recovery phrase or private key.','wc-connect wc-unverified','dapp-disconnect dapp-swap permissions')
add('dapp-disconnect','settings','Disconnect a dApp safely','End a WalletConnect session and separately review any on-chain permissions you granted.','Settings → WalletConnect, or Permissions → Connected apps','Open the connected-apps list and choose the wallet whose sessions you want to inspect.|Identify the session by its website and approved accounts/networks.|Open its controls and disconnect the intended session.|Return to the list and verify that it is no longer connected. Reconnect from the dApp if you later need it.|Open Permissions → Token access or NFT access if you also want to revoke previously granted allowances.|Review and confirm those revocations separately, then check their results.','A WalletConnect session allows a dApp to request actions. Disconnecting removes that session’s access to this wallet connection.|An on-chain allowance survives disconnection. A previously signed permit may also remain usable until its expiry or an applicable invalidation.|Disconnecting is not an on-chain transaction and does not reverse a completed swap or transfer.','If a site still displays an old connected state, refresh it. Check Oath’s session list and on-chain permission status separately.','help-dapps wc-connected','connect-dapp revoke-token-access permit2-access')
add('dapp-swap','activity','Review a token swap from a dApp','Understand which asset you pay, which asset you expect, and the network and limits you are authorizing.','dApp → Swap → Oath approval','Choose the input asset, output asset, amount and network in the dApp. Request its quote.|When Oath opens, confirm the dApp origin, selected wallet/account and network.|Read the input and output assets using their full identities. Check whether an amount is exact, a maximum input or a minimum output.|Review the recipient, native-coin value, network fee and deadline when shown. A token approval or Permit2 signature may arrive as a separate request before the swap.|Open Transaction data for readable operations and the original technical data. If an unfamiliar call cannot be explained, reject it until you can verify its purpose.|Confirm and authenticate only the request you intended. Return to the dApp for any remaining step, then verify the actual transaction outcome.','For recognized router methods Oath displays readable swap bounds and routing operations. Native wrapping/unwrapping is only summarized when the route supports that interpretation.|A quote or simulation is not a guaranteed settlement price. Slippage, price movement, expiry and contract conditions can cause a swap to fail.|Unknown routers, commands or metadata remain explicitly unknown or technical. A safe review must not invent an output token or interpret every arbitrary contract call as a swap.','An approval grants spending access; it is not the swap itself. Verify the spender and limit, then review the separate swap request.','08-dapp-swap wc-approve wc-contract','dapp-transaction-data dapp-signatures send-troubleshooting')
add('dapp-transaction-data','activity','Read human-readable transaction data','Use the decoded details to understand a contract request while keeping the exact technical payload available.','dApp approval → Transaction data','On a transaction approval, check the network, account, destination contract and native value first.|Open Transaction data.|Read the recognized method and its fields: for example recipient, asset, spending limit, swap path or deadline.|For a batch or router execution, inspect each decoded operation, including any optional or unknown operation.|Use the technical/raw-data section when you need the exact selector or calldata. Do not approve simply because a method name looks familiar.|Return to the review and confirm only after the decoded operation agrees with your intended action.','Decoding describes the submitted instructions; it does not certify a contract as safe or show every possible effect of its execution.|Token decimals are resolved for the exact asset. When reliable metadata is missing, exact raw units or addresses are safer than an invented name or amount.|Some complex or unsupported contracts cannot be completely decoded. Reject or independently verify those requests rather than assuming a generic label means a harmless transfer.','Simulation is an estimate and can be incomplete. Always compare the exact network and contract with the dApp action you initiated.','wc-contract 08-dapp-swap','dapp-swap dapp-signatures')
add('dapp-signatures','security','Review messages, sign-ins and token permits','Tell a login challenge apart from a message, token approval or spending authorization.','WalletConnect request → review','Check which website requested the signature and why you expect it now.|Read the full message or structured fields. For sign-in, compare the domain, address and any expiry or nonce details.|For an approval or permit, inspect the token, spender, amount/limit, chain and deadline rather than treating it as a login.|If an editable approval limit is offered, choose only the allowance you intend and review the resulting request.|Reject unreadable, unexpected or unsupported requests. Authenticate only when the requested authorization makes sense.|After signing, return to the dApp. Manage any resulting on-chain allowance in Permissions.','A message signature may have no immediate network fee but can still authorize an action. Permit signatures can grant spending rights when submitted later.|Signing a transaction and broadcasting it are distinct. A dApp can ask for signed bytes and submit them itself; the absence of an immediate History entry does not mean the signature is harmless.|A signature cannot generally be recalled by disconnecting the session. Available nonce invalidation and revocation mechanisms depend on the exact permission.','No legitimate WalletConnect approval asks you to type a recovery phrase or private key into the requesting website.','wc-signin wc-permit2','connect-dapp permit2-access dapp-disconnect')
add('walletconnect-solana','settings','Use Solana dApps and test networks','Review Solana requests on the exact mainnet, Devnet or Testnet cluster approved for the session.','Solana dApp → WalletConnect → Oath','In the dApp, choose the Solana cluster you intend to use and connect with WalletConnect.|Approve the requested cluster in Oath and verify the selected wallet/account. Devnet and Testnet are separate networks from mainnet.|When a request arrives, read its network, fee payer, fee and simulated SOL or token balance changes.|Inspect mint identities and invoked programs, particularly when a token name is unavailable or inspection is incomplete.|For a signing-only request, understand that the dApp receives a signed transaction. For sign-and-send, follow the pending result until confirmation or failure.|When testing, use only test-cluster assets and check the corresponding explorer. Test-cluster submissions do not become mainnet balances or mainnet history.','The selected Solana derivation must match the account requested by the dApp. Switching accounts can invalidate a pending review.|Supported flows include readable message signing, legacy and version-0 transaction signing, supported transaction batches and sign-and-send. Unknown cluster aliases, unsupported versions and durable-nonce transactions are not silently converted to mainnet.|A batch is not a guarantee of atomic execution. Transactions that depend on an earlier batch member can fail independent simulation; Oath does not blindly approve them.','Third-party dApp compatibility varies. A test-cluster connection is not proof that every swap program or request is supported.','help-dapps wc-connect','connect-dapp solana-address-path dapp-swap')
add('walletconnect-thorchain','settings','Review THORChain dApp requests','Check RUNE transfers, deposits and readable cross-chain swap instructions separately.','THORChain dApp → WalletConnect → Oath','Connect the intended THORChain account through the dApp’s WalletConnect flow.|Review the website and approved network before connecting.|For a transaction request, inspect the input asset, amount, destination and memo/deposit instructions.|For a recognized cross-chain swap, compare the receive asset and destination chain as well as the input chain.|Review the fee and any output bounds or deadline shown, then authenticate if you want to proceed.|Follow the transaction result and the dApp’s swap progress. A source-chain confirmation alone does not establish delivery on a different destination chain.','THORChain transactions can use memos to describe actions. A memo is operational data, not just a label for your records.|A cross-chain destination must be valid on that destination network. Do not substitute a same-looking address from another chain.|Unknown or unsupported instructions may not provide a complete readable preview. Verify them independently or reject them.','A direct RUNE send is different from a deposit or cross-chain swap. Review the action name and both sides of a swap.','wc-crossSwap wc-thor','dapp-swap dapp-transaction-data send-tags-and-memos')
add('revoke-token-access','settings','Revoke a token allowance or delegate','Remove a supported permission and verify that access is actually gone on-chain.','Settings → Permissions → Token access','Select the intended wallet in Permissions and wait for the scan.|Open Token access and locate the exact asset under its network heading. Compare the approved spender or delegate.|Swipe a removable row or open its detail and choose the removal action.|Review the wallet, network, approved address, access being removed and fee. Keep the relevant network fee coin available.|Confirm and authenticate when requested. Follow the pending result without resubmitting the same removal unnecessarily.|Open removal history and refresh the permission scan. Treat access as removed only after its result is verified.','Removal uses the permission type’s supported instruction: for example an EVM/TRON allowance reset or a Solana token-account delegate revocation.|A transaction can confirm yet fail to remove the expected access if state changed or the contract behaves differently. Oath checks the resulting permission rather than relying only on a transaction hash.|An NFT collection approval, token allowance, account-control delegation and permanent token delegate have different scopes. Not every row can be revoked by the current account.','Revoking access does not recover funds already spent by a contract. It also does not remove unrelated permissions.','permission-list permission-review','bulk-revoke-access permission-coverage permissions')
add('bulk-revoke-access','settings','Revoke several permissions','Select a group of permissions, review the batch and check each result independently.','Permissions → Token or NFT access → filter menu → Select','Open the access list for the wallet you intend to protect.|Use the filter menu to enter Select mode. Tap rows, Select All or Unselect All; review the visible network groups and selection count.|Tap Revoke All in the native bottom toolbar. This refers to your selected removable items, not every possible permission on every chain.|Review the batch, including network fees and items that cannot currently be prepared. Confirm only the permissions you intend to remove.|Authenticate when requested. You may continue using the app while the queue processes supported items; one failed item does not prevent later items from being attempted.|Open progress/removal history. Check confirmed, pending and failed results individually, then correct failures and retry only the outstanding items.','Each network can require its own transaction and fee. A batch is not a single atomic transaction and may finish with mixed results.|The queue can continue while the app is usable, but iOS can suspend background execution. Reopen and unlock Oath to resume when required; do not assume it runs indefinitely after closing the app.|Refresh coverage after completion. A request to revoke all selected entries does not discover previously unknown approvals or cancel arbitrary off-chain signatures.','Keep enough fee assets on every selected network. Never describe a partly successful batch as fully revoked.','permission-select permission-review','revoke-token-access permission-removal-history permission-coverage')
add('permission-coverage','settings','Understand permission scan coverage','Use scan status to distinguish checked, partial, unavailable and unindexed network results.','Settings → Permissions → Coverage','Select the wallet you want to inspect.|Open Coverage and find the relevant network and last-check time.|Read whether the scan is checked, partial, unavailable or not indexed. Retry a failed or incomplete scan after checking connectivity.|Return to the access categories to inspect permissions that were actually discovered.|If you know an exact token contract and approved address, use Check a contract on a supported network.|Compare public on-chain state when needed and contact support with public network/contract details if a result remains unclear.','A checked scan covers the implemented discovery method, not every possible contract or historical signature in the world.|Partial results can still contain useful permissions. Missing rows are not proof that access is absent; provider limits, custom contracts and unindexed data can prevent discovery.|Solana delegates, TRON approvals and EVM standard approvals differ. Coverage is reported per network rather than treating all accounts as interchangeable.','An empty permission list must not be interpreted as a comprehensive security audit.','help-permissions permission-check','permissions check-contract-access')
add('check-contract-access','settings','Check a contract and approved address','Look up a specific supported permission when you know the exact contract and spender.','Permissions → Coverage or access-list menu → Check a contract','Open Check a contract.|Choose the network using the network row with its logo.|Choose the access type you intend to inspect. The fields depend on that type.|Paste the token or collection contract and approved address into their connected fields. Enter a token ID or additional identity if the form requests it.|Compare the full addresses with trusted information, then tap the top checkmark.|Read the returned access and review a removal if supported. If the check fails, confirm the network and field formats before retrying.','The approved address is the spender or operator, not automatically your own wallet address. A contract alone is not enough to identify an allowance.|Selecting a collection-wide approval is different from checking access to one NFT. Permit2 checks also need their appropriate token identity.|This targeted lookup does not scan every possible spender. It answers the specific supported permission query you supplied.','Do not paste a private key or recovery phrase into either address field.','permission-check permission-review','revoke-token-access permission-coverage')
add('permit2-access','settings','Understand Permit2 and signed approvals','Separate an existing allowance from a signature that may authorize future spending.','Permissions → Token access → Permit2 entry','Find the permission for the intended wallet, token, network and spender.|Read the current allowance and any expiry/nonce details provided.|Choose allowance removal when you want to remove the current supported on-chain access.|If a separate nonce-invalidation action is offered for the permission, read its purpose and review it independently.|Confirm the chosen action and fee, then check its verified result.|Disconnect unused dApp sessions separately and review other approvals for the same token.','Permit2 can involve multiple layers of authorization. Removing one current allowance is not a universal cancellation of every signature or spender.|Nonce invalidation is a different on-chain action from allowance removal. It applies to the supported nonce scope shown in the review, not arbitrary signatures across all protocols.|Unknown off-chain permits cannot be exhaustively discovered by scanning a wallet. Be cautious about signatures as well as transactions.','An unlimited allowance is a spending authorization, not your token balance.','wc-permit2 permission-list','dapp-signatures revoke-token-access')
add('permission-removal-history','activity','Check revocation progress and failures','Confirm each permission removal rather than assuming a completed queue means every item succeeded.','Permissions → Removal history','Open Permissions for the wallet used in the revocation.|Open the history/progress entry for the removal or batch.|Read each item’s network, asset, submission status and access result.|For pending items, wait and refresh or reopen Oath after connectivity returns.|For failures, read the reason, fix fee or network problems and prepare a new review for that item only.|Rescan the access list and compare the exact permission after confirmation.','Submission, chain confirmation and verification that access is removed are distinct stages.|A batch can continue after one error and therefore produce successful and failed rows together. Review all selected entries, not just the last notification.|Closing the app may pause work; reopening and unlocking allows supported pending work to resume.','Do not retry an uncertain transaction blindly. Use its existing public transaction ID to establish the outcome first.','permission-review help-permissions','bulk-revoke-access transaction-status')
add('account-control-permissions','security','Review account-control and permanent delegates','Recognize permissions that affect more than a single token allowance.','Settings → Permissions → Account control','Choose the intended wallet and open Account control.|Read the network, delegate or permission key and the scope shown for the entry.|Distinguish an account-control delegation from a token spending allowance.|If removal is offered, review exactly what it changes and whether the current wallet can authorize it.|Confirm only after checking the fee and result you expect. Verify the updated state after confirmation.|If the permission is permanent, unsupported or cannot be safely changed by this account, do not assume a token-level revoke will remove it.','Supported account-control inspection includes network-specific cases such as EVM delegation and TRON permission keys. These do not share one universal removal operation.|A Token-2022 permanent delegate is part of the mint’s authority design; an individual holder cannot simply revoke that authority like an ordinary token-account delegate.|A familiar asset logo or a small current balance does not make broad account control harmless. Read the scope before acting.','When the app cannot safely remove a permission, it should remain a limitation rather than be reported as removed.','help-permissions permission-list','permissions permission-coverage revoke-token-access')
add('last-wallet-reset','wallets','Remove the last active wallet','Understand the final-wallet reset and clear Recently Deleted only after protecting your recovery options.','Settings → Wallets → Edit → remove final wallet','Confirm you can recover the final wallet and any wallets in Recently Deleted before starting.|Choose remove for the last active wallet.|If Recently Deleted contains wallets, read the prompt to permanently remove them first. Cancel if you need to restore or back up any of them.|Confirm the requested permanent removal and complete authentication when security requires it.|Confirm removal of the last active wallet and wait for the local reset to finish.|Oath returns to Welcome. To use a wallet again, import its recovery material or restore an encrypted backup.','The final wallet is not left as the only item in Recently Deleted. The flow clears retained wallets before resetting the installation to its no-wallet state.|This removes local access and app data. Blockchain funds and previously granted on-chain permissions are unaffected; deleting a wallet does not revoke access.|Existing cloud backup files are separate. Keep the correct password and any extra recovery passphrase needed to restore them.','Do not delete the last local copy of recovery material unless you have an independent, usable backup.','07-wallets help-recently-deleted welcome','remove-wallet reset-app restore-icloud')
add('upgrade-existing-wallets','wallets','Open existing wallets after an Oath update','Unlock normally and let Oath prepare compatible existing wallets without creating replacements.','Install update → launch → unlock','Install the Oath update over the existing app; do not uninstall an app that contains your only usable recovery copy.|Open Oath and enter your existing app passcode if requested. Let the loading/unlock flow finish.|If biometric authorization needs to be renewed, enable it when offered or explicitly continue with passcode protection.|On Home, check the selected wallet and open Wallets to review the names of your other wallets.|Compare receiving addresses on the intended networks before transferring. Balances and history may take time to refresh.|If the upgrade cannot safely import a wallet type, stop and follow the error guidance rather than resetting or creating a replacement wallet over it.','The upgrade preserves compatible wallet material and names using the new wallet rules. Unsupported multisig or multi-key collections are stopped safely rather than silently reduced to a different wallet.|An existing passcode is preserved where compatible. Biometric authorization can require a fresh system prompt; it must not be assumed from an old toggle alone.|Cached blockchain information is disposable and fetched again. An initially loading value is different from loss of the underlying wallet.','Never send your passcode or recovery material to support. Keep the original recovery route until you have verified the upgraded wallets.','passcode 07-wallets','unlock-wallet move-to-new-phone restore-icloud')
add('balance-change','assets','Understand the balance-change capsule','Read the observed change under the portfolio total without mistaking deposits for investment profit.','Home → capsule beneath total balance','Open Home for the wallet you want to inspect.|Read the total and the change capsule underneath it.|Note the time period shown and whether the change is positive, negative or unchanged.|Review History for deposits, withdrawals and other activity that may have changed the balance.|Refresh to update available balances and market prices. Compare asset quantities when the currency value changes unexpectedly.','The change is based on available wallet-value snapshots. Deposits, withdrawals, asset discovery and market-price changes can all affect it.|Green and red help indicate direction; the text and sign remain important. A value change is not a tax report or a calculation of realized trading profit.|The capsule is a compact display. The removed balance-history bottom sheet and its range controls are not part of this flow.','A missing or incomplete baseline can limit the comparison. Do not infer a full period of trading performance from a newly imported wallet.','01-portfolio 03-activity','portfolio-values refresh-balances')
add('asset-filters','assets','Filter the Home assets list','Narrow the portfolio by network and available asset filters without changing ownership.','Home → Assets → filter icon','Open Home and tap the filter icon beside Assets.|Review the available network and asset-visibility choices.|Select the criteria you want and apply the sheet’s confirmation action.|Read the visible count and any active-filter indication when searching for an expected asset.|Reopen filters and reset the choices when you want the full supported list again.','Filtering changes what is displayed; it does not sell a token, delete its key or revoke a contract allowance.|A token may be absent because of a filter, unavailable discovery or an unsupported identity. Compare the exact network and contract before concluding it was lost.|Use Search with a contract or mint to find a supported token independently of its displayed name.','A displayed logo or name is not verification that an asset is legitimate.','01-portfolio 06-send-assets','search-assets add-custom-token token-not-found')
add('token-prices-and-logos','assets','Understand token logos and missing prices','Distinguish token identity, balance, artwork and market data when searching by contract or mint.','Wallet → Search → token address → asset','Paste the exact contract or mint address into asset search.|Compare the network and full identity of every matching result before adding one.|Open the asset and inspect its token quantity, logo and any available price separately.|If a price is unavailable, pull to refresh and check the quote’s timestamp. A missing quote is not a confirmed price of zero.|Use Asset Information to compare the token identity with a trusted source. Do not match by ticker alone.|If the same supported token still has inconsistent artwork or prices, report its public contract/mint and network to support.','Logos and quotes come from separate metadata and market-data paths. A token can have a valid logo and on-chain balance without a usable market quote.|Contract-based price lookup uses the exact chain and token reference and can consult multiple providers. Sparse liquidity, unsupported markets, rate limits or outages can still prevent a reliable price.|A quote is an estimate, not a promise that you can sell the entire holding at that price. Never use a logo or a displayed dollar value as evidence of contract safety.','No provider can supply a trustworthy price for every token. Unknown prices should remain unavailable rather than fabricated.','02-bitcoin-market 01-portfolio','add-custom-token prices-chart unverified-tokens')
add('haptic-feedback','settings','Turn haptic feedback on or off','Choose whether Oath provides tactile feedback for supported controls and outcomes.','Settings → Haptic Feedback','Open Settings from the Home toolbar.|Find Haptic Feedback and change its switch.|Return to a normal selection or confirmation control to use the preference.|If you do not feel feedback, check the device’s support and system settings as well.','Haptics supplement visible labels, progress and results. A vibration is not proof that a blockchain transaction has confirmed.|Feedback depends on the device and supported interaction. A simulator cannot demonstrate how a physical device feels.|Turning feedback off does not change transaction checks, signing or network fees.','Read the on-screen status even when you feel success feedback.','help-settings','appearance confirmation-checkmark')
add('use-thorchain','assets','Use THORChain and RUNE','Receive RUNE, send on THORChain and distinguish a direct transfer from a dApp swap.','Home → THORChain','Open THORChain or search for RUNE in Wallet search.|Check the native quantity and use Receive for the THORChain address.|For a direct transfer, tap Send and enter the recipient and any required memo.|Review the amount, network and fee before authorizing.|After submission, check History and the public explorer record.|For a dApp deposit or cross-chain swap, review that separate WalletConnect request and its destination chain.','The native RUNE balance belongs to THORChain. A token with the same ticker on another chain is a different asset.|A direct send does not automatically execute a cross-chain swap. The dApp request must specify its deposit and swap instructions.|Keep enough RUNE for applicable fees and review any memo carefully.','A source-chain confirmation alone does not prove a cross-chain destination payment is complete.','chain-thorchain wc-crossSwap','walletconnect-thorchain send-availability')
for slug,name in [('use-hyperevm','HyperEVM'),('use-monad','Monad'),('use-unichain','Unichain')]:
 add(slug,'assets',f'Use {name} in Oath',f'Find the correct {name} account, native fee asset and tokens without confusing other EVM deployments.',f'Wallet → Search → {name}',f'Select Wallet, open Search and find {name}.|Open the intended native asset or token and inspect Asset Information.|Use Receive to copy the public address for this network. Confirm the sending service offers the same network.|For tokens, search the exact contract address and verify the network before adding.|Use Send for supported transfers, keeping the native fee asset available.|Review History and open the transaction’s network-specific explorer after submission.',f'{name} uses an EVM account address, but its balances and token contracts are separate from other EVM chains.|Provider coverage for token discovery, logos, prices and history can differ. A missing quote is not a zero token balance.|Connecting a dApp requires its own network approval; adding an asset to Home does not authorize a dApp.', 'A shared 0x address does not bridge funds. Choose the exact network on both sides of a transfer.',f'chain-{slug[4:]} 06-send-assets','evm-networks add-custom-token send-availability')
# Attach feature-specific explanations to all retained guides rather than leaving terse/empty bodies.
extras={
'create-wallet':'A newly created recovery-phrase wallet has new keys and addresses. Choosing a familiar name does not restore an older wallet; use Import or Restore for that.|Keep the recovery phrase and any additional passphrase independently of the app passcode. Before funding, verify that you have a usable recovery route.',
'import-recovery-phrase':'Import reconstructs supported accounts from the phrase; it does not move coins on-chain. Enter the original order and language, and never replace an invalid word by guessing.|A separate BIP-39 passphrase creates different accounts. If your previous wallet used one, restore that exact passphrase wallet and compare addresses before concluding a balance is missing.',
'scan-recovery-qr':'A recovery QR contains secret material. Scan it privately from a source you control, not from a public website or a person offering support.|The import validation still applies after scanning. A recognized QR is not proof that the wallet belongs to you or has a trustworthy history.',
'import-private-key':'A private-key wallet usually restores one key or a supported scoped account, not all accounts generated by a recovery phrase. Choose the import type that matches your original recovery material.|Review the address after import. A valid key in the wrong network or derivation context can show an account you did not intend.',
'private-key-formats':'Do not convert formats by manually trimming characters or discarding bytes. Use the original supported export and correct network choice.|If Oath rejects a format, stop and identify the original wallet’s export type. A public address, extended public key or keystore password alone is not a private key.',
'first-passcode':'The six-digit app passcode protects local wallet access; it is not the recovery phrase or your iCloud backup password.|Keep all three roles separate. Losing the phone can require recovery material even when you remember the app passcode.',
'customize-wallet':'A wallet name and color are local labels that help you distinguish accounts. Editing them does not change the wallet’s blockchain addresses.|Use names that remain clear in the switcher and transaction review. Check the active wallet after returning Home.',
'reorder-wallets':'Reordering changes the list order, not the active wallet or its keys. The check badge identifies selection independently of position.|Use the native editing handles and finish with the toolbar checkmark so the list exits editing mode.',
'add-passphrase':'The additional BIP-39 passphrase is part of the key derivation. Every different value, including differences in case or spaces, produces a different wallet.|It is not the app passcode and not an iCloud encryption password. Record the exact phrase and passphrase together in a secure recovery plan; the passphrase wallet needs its own verification and backup.',
'backup-all-wallets':'The backup flow encrypts the supported wallet material before saving backup files to your iCloud Drive. The backup password is required to restore those files.|Check each wallet’s outcome. A batch can contain a failed upload even when another wallet completed; retain an independent recovery copy until the relevant upload is confirmed.',
'backup-one-wallet':'Select the wallet by name before enabling its backup. A backup for one wallet is not automatically a backup for every other wallet in the app.|Keep Oath open until its upload status completes. If iCloud is unavailable, fix the account, Drive, storage or connectivity issue and retry.',
'backup-password':'Choose a backup password you can recover without access to this phone. It is separate from the six-digit app passcode.|Oath cannot decrypt an existing file with a newly chosen password. Keep the password that was used for each backup file you retain.',
'restore-icloud':'Restoring downloads an encrypted file and requires its own backup password. Signing into the correct Apple Account alone is not sufficient to decrypt it.|After restoration, compare the wallet name and public addresses with the original. Network balances and transaction history are fetched separately; allow refresh to finish.',
'view-recovery-phrase':'Anyone with the full recovery phrase and any required passphrase can control the wallet. View it only in a private place and do not send it to support.|The screenshots in this guide deliberately stop at the protective screen. They never show a populated recovery phrase.',
'view-private-key':'A private key grants control of its corresponding account. Sharing it is not the same as sharing a public receiving address.|Choose the intended network and supported account/address type before exporting. These screenshots deliberately avoid showing a private-key value.',
'enable-face-id':'Face ID or Touch ID is a convenience for the protected local vault. The app passcode remains the fallback when biometric authentication is unavailable or canceled.|Changes to device biometrics or secure credentials can require renewed authorization. Check the resulting switch rather than assuming the system prompt succeeded.',
'forgot-passcode':'Oath support cannot tell you your passcode or reconstruct a missing recovery phrase. Resetting the app is not a way to bypass decryption of the existing vault.|Do not remove the app or its final wallet while it holds your only usable recovery copy. Preserve the device and seek guidance using nonsecret information.',
'address-book':'A contact name is your own label, not verified ownership. Add the person’s public receiving address under its exact network and confirm it with them.|When sending, check the resolved address even if you recognize the contact name. Contacts do not eliminate the need to verify the recipient.',
'contact-address':'The same person may have several network addresses. Save each under the correct network and use a label that distinguishes its purpose.|An address format can be valid without belonging to the intended recipient. Compare it through a trusted channel before saving or using it.',
'currency':'Currency changes the app’s valuation and available fiat-entry display. It does not convert coins, execute an exchange or alter the units recorded on-chain.|A missing conversion rate or token quote can limit local-currency values. Use the actual asset quantity to identify the amount held or sent.',
'language':'Changing the language localizes interface labels. Canonical network names, token symbols, addresses and transaction IDs remain identifiers rather than translated assets.|Right-to-left layout can move controls, but the action names and full addresses remain the basis for checking a transaction.',
'appearance':'Light, Dark and System control interface appearance. Wallet color and the launcher icon are separate preferences.|System follows the device appearance. Contrast and accessibility settings can affect the exact rendering shown in examples.',
'in-app-browser':'Explorer, help and project links open in the native browser surface when supported. Check the hostname before interacting with a third-party page.|A browser page is external content. Do not enter recovery words, private keys or an app passcode into a site because it opened from the wallet.',
'network-fee':'The fee pays for network execution or inclusion and is separate from the amount transferred. Token sends commonly need a native fee asset as well as the token.|A failed on-chain transaction may still consume fees. An estimated local-currency fee can vary with the market price and is not an exact historical fiat receipt.',
'wrong-network':'Public addresses can share a format across different networks. That does not make the chains interchangeable or prove a deposit service can recover the transfer.|If already sent, retain the transaction ID and contact the receiving service using official channels. Do not pay an unsolicited recovery service or disclose keys.',
}
for slug,text in extras.items():
 if slug in A:
  A[slug]['body']+=text.split('|')
