# Topic-specific closing instructions and explanation for the smaller retained guides.
topic_notes={
'start':('Before you finish','Verify the wallet name and intended public address after setup. A newly generated wallet and an imported wallet can have the same label while controlling different accounts.'),
'wallets':('Check the result','Return to Wallets and confirm the intended wallet and active selection. A local management action does not itself transfer funds or change network permissions.'),
'backup':('Verify recovery readiness','Treat the backup as usable only when the relevant operation has completed and you retain the correct recovery material or file password. Loading, preparing and unavailable states are not successful backups.'),
'security':('Confirm protection','Review the resulting security setting before leaving. Public account activity remains visible on-chain even when the app is locked or its balance display is hidden.'),
'assets':('Read each data field separately','Quantity, market price, logo and transaction history are separate data. An unavailable quote or delayed provider response does not by itself establish that an asset balance is zero.'),
'receive':('Verify before funding','Receiving shares a public destination; it does not sign a transfer. The sender must select the same network and asset deployment as the address you are showing.'),
'activity':('Verify the outcome','Open the exact transaction and compare its network and full identifier. A pending status, a signed request and a confirmed transfer represent different stages.'),
'settings':('Check the saved choice','Return to the relevant screen to confirm the setting or saved entry. Canceling an edit should not be treated as an applied change.')}
for a in articles:
 if len(a['body'])<3:
  a['body'].append(topic_notes[a['category_id']][1])
 # The old generic related links were often unrelated to the feature.
 if a['slug'] in ['appearance','app-icon','currency','language','haptic-feedback']:a['related']=[s for s in ['appearance','app-icon','currency','language','haptic-feedback'] if s!=a['slug']][:3]
 a['tags']=sorted(set(a['tags']+[a['slug'].replace('-',' '),'4.0.3']))
